class Solution {
    public int[] rearrangeArray(int[] nums){
        Arrays.sort(nums);
        for(int i=1;i+1<nums.length;i+=2){
            int temporary=nums[i];
            nums[i]=nums[i+1];
            nums[i+1]=temporary;
        }
        return nums;
    }
}

code.kotlin:
class Solution {
    fun rearrangeArray(nums:IntArray):IntArray{
        nums.sort();
        var i=1;
        while(i+1<nums.size){
            val temporary=nums[i];
            nums[i]=nums[i+1];
            nums[i+1]=temporary;
            i+=2
        };
        return nums
    }
}

